            "<span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { firstValueFrom } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> 'rxjs'</span><span style=\"color:#E1E4E8\">;</span>",
            "<span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { PaymentFlowEventsEnum, Stripe } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@capacitor-community/stripe'</span><span style=\"color:#E1E4E8\">;</span>",
            "",
            "<span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">async</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#E1E4E8\">  Stripe.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(PaymentFlowEventsEnum.Completed, () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'PaymentFlowEventsEnum.Completed'</span><span style=\"color:#E1E4E8\">);</span>",
            "<span style=\"color:#E1E4E8\">  });</span>",
            "",
            "<span style=\"color:#a0aab5\">  // Connect to your backend endpoint, and get every key.</span>",
            "<span style=\"color:#F97583\">  const</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#79B8FF\">paymentIntent</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">ephemeralKey</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">customer</span><span style=\"color:#E1E4E8\"> } </span><span style=\"color:#F97583\">=</span><span style=\"color:#F97583\"> await</span><span style=\"color:#B392F0\"> firstValueFrom</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.http.</span><span style=\"color:#B392F0\">post</span><span style=\"color:#E1E4E8\">&lt;{</span>",
            "<span style=\"color:#FFAB70\">    paymentIntent</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">;</span>",
            "<span style=\"color:#FFAB70\">    ephemeralKey</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">;</span>",
            "<span style=\"color:#FFAB70\">    customer</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">;</span>",
            "<span style=\"color:#E1E4E8\">  }&gt;(environment.api </span><span style=\"color:#F97583\">+</span><span style=\"color:#9ECBFF\"> 'intent'</span><span style=\"color:#E1E4E8\">, {}));</span>",
            "",
            "<span style=\"color:#a0aab5\">  // Prepare PaymentFlow with CreatePaymentFlowOption.</span>",
            "<span style=\"color:#F97583\">  await</span><span style=\"color:#E1E4E8\"> Stripe.</span><span style=\"color:#B392F0\">createPaymentFlow</span><span style=\"color:#E1E4E8\">({</span>",
            "<span style=\"color:#E1E4E8\">    paymentIntentClientSecret: paymentIntent,</span>",
            "<span style=\"color:#a0aab5\">    // setupIntentClientSecret: setupIntent,</span>",
            "<span style=\"color:#E1E4E8\">    customerEphemeralKeySecret: ephemeralKey,</span>",
            "<span style=\"color:#E1E4E8\">    customerId: customer,</span>",
            "<span style=\"color:#E1E4E8\">  });</span>",
            "",
            "<span style=\"color:#a0aab5\">  // Collect payment details. The Intent is not confirmed yet.</span>",
            "<span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> presentResult</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> Stripe.</span><span style=\"color:#B392F0\">presentPaymentFlow</span><span style=\"color:#E1E4E8\">();</span>",
            "<span style=\"color:#E1E4E8\">  console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(presentResult); </span><span style=\"color:#a0aab5\">// { cardNumber: \"●●●● ●●●● ●●●● ****\" }</span>",
