            "<span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { firstValueFrom } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> 'rxjs'</span><span style=\"color:#E1E4E8\">;</span>",
