            "<span style=\"color:#E1E4E8\">  }&gt;(environment.api </span><span style=\"color:#F97583\">+</span><span style=\"color:#9ECBFF\"> 'intent'</span><span style=\"color:#E1E4E8\">, {}));</span>",
            "",
            "<span style=\"color:#a0aab5\">  // Prepare Google Pay</span>",
            "<span style=\"color:#F97583\">  await</span><span style=\"color:#E1E4E8\"> Stripe.</span><span style=\"color:#B392F0\">createGooglePay</span><span style=\"color:#E1E4E8\">({</span>",
            "<span style=\"color:#E1E4E8\">    paymentIntentClientSecret: paymentIntent,</span>",
