            "<span style=\"color:#E1E4E8\">    }],</span>",
            "<span style=\"color:#E1E4E8\">    merchantIdentifier: </span><span style=\"color:#9ECBFF\">'merchant.com.getcapacitor.stripe'</span><span style=\"color:#E1E4E8\">,</span>",
            "<span style=\"color:#E1E4E8\">    countryCode: </span><span style=\"color:#9ECBFF\">'US'</span><span style=\"color:#E1E4E8\">,</span>",
            "<span style=\"color:#E1E4E8\">    currency: </span><span style=\"color:#9ECBFF\">'USD'</span><span style=\"color:#E1E4E8\">,</span>",
            "<span style=\"color:#E1E4E8\">  });</span>",
            "",
            "<span style=\"color:#a0aab5\">  // Present Google Pay</span>",
            "<span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> result</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> Stripe.</span><span style=\"color:#B392F0\">presentGooglePay</span><span style=\"color:#E1E4E8\">();</span>",
            "<span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (result.paymentResult </span><span style=\"color:#F97583\">===</span><span style=\"color:#E1E4E8\"> GooglePayEventsEnum.Completed) {</span>",
